"""Reporting after all scientific selections and confirmation are frozen."""
import csv
from pathlib import Path
import numpy as np
from .core import *
from .run import BASE,OUTPUTS

def vec(a):return '['+', '.join(f'{float(v):.5f}' for v in np.asarray(a).reshape(-1))+']'
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|',*['| '+' | '.join(map(str,r))+' |' for r in rows]])
def report(run):
 for name in ['prepare_lock.json','discovery_lock.json','native_lock.json','confirmation_lock.json']:verify(run,name)
 hyp=read(run/'transcoder_hypotheses.json');native=read(run/'native_explanations.json');details=read(run/'confirmation_details.json');man=read(run/'context_manifest.json');metrics=list(csv.DictReader(open(run/'confirmation_metrics.csv')))
 # Labels and expected pairs enter only this post-lock diagnostic reporting stage.
 from ..data import targets
 expected={4:(7,8),6:(11,12),0:(0,1)};summary=[];secondary={}
 for j in OUTPUTS:
  hh=hyp[str(j)];nn=native[str(j)];dt=details[str(j)];pair=hh['pair'];bank=man[f'{pair[0]},{pair[1]}']['H'];bg=bank['background_keys'];nd=dict(np.load(run/f'confirmation_native_{j}.npz'));tc=dict(np.load(run/f'confirmation_student_{j}.npz'));preds=dict(np.load(run/f'confirmation_predictions_{j}.npz'));rows=[r for r in metrics if int(r['output'])==j]
  def metric(method,k=None):return next(r for r in rows if r['method']==method and (k is None or int(r['budget'])==k))
  kg=nn['primary']['guided']['budget'];kn=nn['primary']['native_only']['budget'];gm=metric('guided',kg);nm=metric('native_only',kn);sm=metric('student');ids=nn['sets']['guided'][str(kg)];sel=preds[f'guided_k{kg}_r0'];truth=nd['total'];labels=targets(corners(bg,pair))[:,:,j];secondary[str(j)]={'teacher_primitive_agreement':float(np.mean((truth>=.5)==labels)),'student_primitive_agreement':float(np.mean((tc['total']>=.5)==labels)),'label_usage':'post-lock diagnostic only'}
  lines=[f'# Output {j}: nominated inputs {tuple(pair)}', '',f'Executed frozen v0.4 development analysis. Expected research pair {expected[j]}; automatic top pair {tuple(pair)}. This is procedural student-first exploration with prospectively locked checks, not fully blinded discovery. No training, readout fitting, hidden intervention, or final-population scoring occurred.','', '## What the transcoder proposed first','',table(['rank','pair','mean absolute joint','signed joint','contexts'],[[r['rank'],(r['i'],r['k']),f"{r['score']:.6f}",f"{r['signed_mean']:.6f}",r['n']] for r in hh['top3']]),'',hh['conditional_hypothesis'],'',f"Discovery mean coefficients [baseline, ai, ak, joint] = {vec(hh['mean_alpha'])}; SD {vec(hh['alpha_sd'])}. Panel IDs {hh['panel']}. Gamma={hh['gamma']:.8f}; remaining-unit mean coefficients={vec(hh['remaining_units_mean_alpha'])}.",'','Full K rows, bias, all nine A writes, per-unit gate counts, q ranges, margins and complete signed responses are in [hypotheses](transcoder_hypotheses.json) and the discovery_student NPZ. [Discovery lock](discovery_lock.json) was saved before native selection.','', '## Original implementation examined','',f'C1=W1@P columns {pair}, R=Q.T@W2 row {j}, b1 and actual ReLU gates were used. R is an effective predicted-output readout, not a ground-truth hidden decoder. beta={nd["beta"][j]:.8f}. A negative write subtracts from the output; it does not inhibit a hidden neuron.','',f"Fixed guided primary k={kg}, IDs={ids}; discovery pass={nn['primary']['guided']['discovery_pass']}. Native-only primary k={kn}, discovery pass={nn['primary']['native_only']['discovery_pass']}. Primary budgets were fixed before confirmation. Greedy forward plus at most five improving single swaps used unmodified coefficients and true bias; no new intercept. The independent sets and every step are in [native explanations](native_explanations.json) and selector traces.",'','## Worked confirmation background and nuisance change','']
  work=nn['worked_selection'];worked=[work['background']]
  if work['matched']:worked.append(work['matched'][2])
  lines += [f"Metadata rule: {work['rule']}. Eligible matched nuisance edges in sampled confirmation bank: {work['matched_edge_count']}. Corner order throughout is [00,01,10,11]. Backgrounds are zero on the nominated pair.",'']
  # Stable display subset: smallest six IDs in already frozen groups/panel, not result cherry-picking.
  for b in worked:
   n=bg.index(b);active=np.flatnonzero(inputs([b])[0]).tolist();lines += [f'### Background key {b}, active nonpair coordinates {active}','',f"Original-data membership of corners: {bank['training_overlap'][n]}. The four keys are {bank['corner_keys'][n]}.",'']
   for label,array,selected in [('Native',nd,ids),('Student',tc,hh['panel'])]:
    display=selected[:6];allv=array['signed'][n];other=[u for u in selected if u not in display];omitted=[u for u in range(allv.shape[-1]) if u not in selected];rows2=[]
    for u in display:
     ucoef,vcoef=array['C'][u,pair];qv=array['q'][n,u];pre=array['pre'][n,:,u]
     rows2.append([u,f"{array['b'][u]:.5f}",f'{qv:.5f}',f'{ucoef:.5f}, {vcoef:.5f}',f"{array['R'][j,u]:.5f}",vec(pre),vec(np.maximum(pre,0)),vec(allv[:,u])])
    rows2 += [['other selected units', '—','—','—','—','—','—',vec(allv[:,other].sum(-1))],['omitted remainder','—','—','—','—','—','—',vec(allv[:,omitted].sum(-1))],['actual output bias','—','—','—','—','—','—',vec(np.repeat(array['beta'][j],4))]]
    lines += [f'**{label} computation.** For each row p=q+u·ai+v·ak, h=max(p,0), contribution=write·h. Gate turns on when u·ai+v·ak > −q. q=b+Σ(nonpair C·background). Numerical p exposes every threshold and equality margin.', '',table(['unit','b','q','u,v','write','p corners','h corners','signed corners'],rows2),'',f"Selected sum plus true bias={vec(allv[:,selected].sum(-1)+array['beta'][j])}; omitted={vec(allv[:,omitted].sum(-1))}; full={vec(array['total'][n])}.",'']
    thresholds=[[u,vec([0,-array['C'][u,pair[1]],-array['C'][u,pair[0]],-array['C'][u,pair].sum()]),f"{array['q'][n,u]:.6f}",vec(array['C'][u,active]),f"{np.abs(array['pre'][n,:,u]).min():.6g}"] for u in display]
    lines += [table(['unit','q boundaries for 00,01,10,11','actual q','nonpair coefficients in active order','min margin'],thresholds),'']
   lines += [table(['accounting term','corners','[baseline, ai, ak, joint]'],[['teacher',vec(truth[n]),vec(polynomial(truth[n]))],['guided + beta',vec(sel[n]),vec(polynomial(sel[n]))],['omitted native',vec(truth[n]-sel[n]),vec(polynomial(truth[n]-sel[n]))],['full student',vec(tc['total'][n]),vec(polynomial(tc['total'][n]))],['student minus teacher',vec(tc['total'][n]-truth[n]),vec(polynomial(tc['total'][n]-truth[n]))]]),'']
  if len(worked)==2:
   b0,bit,b1=work['matched'];n0,n1=bg.index(b0),bg.index(b1)
   for label,array,selected in [('native',nd,ids),('student',tc,hh['panel'])]:
    change=array['q'][n1]-array['q'][n0];switch=np.sum((array['pre'][n1]>0)!=(array['pre'][n0]>0),axis=0)
    lines += [f'Matched {label}: add nuisance a{bit}; q change is exactly C[:,{bit}], maximum numerical identity error {np.max(np.abs(change-array["C"][:,bit])):.3g}. Total corner change={vec(array["total"][n1]-array["total"][n0])}.', '',table(['unit','q change','switched corners','signed corner change'],[[u,f'{change[u]:.6f}',int(switch[u]),vec(array['signed'][n1,:,u]-array['signed'][n0,:,u])] for u in selected[:6]]),'']
  else:lines += ['No matched nuisance flip is available in the fixed sampled confirmation bank; no outside context was substituted.','']
  lines += ['## Fixed-set confirmation','',f"N={len(bg)} complete backgrounds; density counts={bank['density']}; overlap memberships={dt['training_overlap_counts']}. Train-unseen row and all-four-unseen-context errors are separately recorded in CSV. Contexts were selected by complete-corner exclusions and same-partition hashes; they are conditioned development backgrounds, not IID generator draws. Confirmation outputs were first computed after both locks.",'',f"Teacher mean coefficients={vec(dt['teacher_mean_alpha'])}, SD={vec(dt['teacher_sd_alpha'])}; student={vec(dt['student_mean_alpha'])}. Post-lock primitive agreement: {secondary[str(j)]}. These are teacher approximation errors, not exact ground-truth Boolean computations.",'']
  curves=[]
  for k in BUDGETS:
   g=metric('guided',k);n=metric('native_only',k);rr=[r for r in rows if r['method']=='random' and int(r['budget'])==k]
   curves.append([k,f"{float(g['corner_mae']):.5f}",f"{float(g['corner_p95']):.5f}",f"{float(g['joint_mae']):.5f}",g['profile_pass']+'/'+g['joint_pass'],f"{float(n['corner_mae']):.5f}",f"{float(n['joint_mae']):.5f}",n['profile_pass']+'/'+n['joint_pass'],f"{np.mean([float(r['corner_mae']) for r in rr]):.5f}"])
  lines += [table(['k','guided MAE','guided p95','guided joint MAE','profile/joint pass','native MAE','native joint MAE','profile/joint pass','random mean MAE (20)'],curves),'',table(['method','MAE','RMSE','p95','max','joint MAE','profile/joint pass'],[[name,*[f"{float(r[key]):.6f}" for key in ['corner_mae','corner_rmse','corner_p95','corner_max','joint_mae']],r['profile_pass']+'/'+r['joint_pass']] for name,r in [('full student',sm),(f'guided k{kg}',gm),(f'native k{kn}',nm)]]),'',table(['primary guided coefficient','signed error','MAE','max absolute'],[[['baseline','ai','ak','joint'][t],*[f"{float(gm[f'alpha{t}_{suffix}']):.6f}" for suffix in ['signed_error','mae','max']]] for t in range(4)]),'',f"Native omitted remainder (teacher − primary guided with beta): mean absolute {float(gm['corner_mae']):.6f}, SD {float(gm['remainder_sd']):.6f}, min {float(gm['remainder_min']):.6f}, max {float(gm['remainder_max']):.6f}. It is retained at every corner and coefficient, never folded into a fitted intercept. All budget-specific signed/absolute coefficient errors, training-overlap metrics, and random replicates are in [confirmation metrics](confirmation_metrics.csv).",'']
  gates=dt['gate_validation'];lines += [table(['native unit','confirmation gate counts (bit mask)','fraction differing from discovery modal','11-only fraction','q range'],[[u,str(gates[str(u)]['gate_counts']),f"{gates[str(u)]['invariant_modal_failure_fraction']:.4f}",f"{gates[str(u)]['only11_fraction']:.4f}",vec(gates[str(u)]['q_range'])] for u in ids[:6]]),'','Gate masks use bit weights [1,2,4,8] for [00,01,10,11]; 8 is 11-only, 2/4 are missing-partner-only patterns. Modal-pattern changes refute an unconditional gate description, while the exact q-dependent hinge equations remain valid. Complete unit counts, near-zero margins, failures, nuisance errors and positive/negative sums are in [confirmation details](confirmation_details.json).','']
  canc=dt['cancellation'][f'guided_k{kg}_r0'];lines += [f"Primary selected positive corner sums averaged over contexts={vec(canc['positive_corner_mean'])}; negative sums={vec(canc['negative_corner_mean'])}. Mean sum of absolute contributions={canc['mean_absolute_sum']:.6f}; mean absolute net={canc['mean_absolute_net']:.6f}. Cancellation is measured, not treated as evidence of a hidden feature code.",'']
  nus=dt['nuisance_metrics'].get(f'guided_k{kg}_r0');lines += [f"Matched nuisance primary errors: {nus}. Signed contribution profiles of fixed selected neurons on all nine outputs are stored in collateral_{j}.npz. This is output accounting, not an executed ablation.",'']
  if j==6:lines += ['For XOR, the baseline and both single-input terms above are necessary: the diagnostic target coefficients are [0,1,1,−2]. A negative joint term alone cannot establish XOR. Additive and compensating units, true bias, and omitted response must all be retained.','']
  lines += ['A positive joint contribution can also come from a negative output write multiplying a suppressed response. Gate signs and complete corner vectors above determine its interpretation. No hidden unit sends an inhibitory signal to another hidden unit in this one-layer MLP.','']
  topok=any((r['i'],r['k'])==expected[j] for r in hh['top3']);gwin=sum(float(metric('guided',k)['corner_mae'])<float(metric('native_only',k)['corner_mae']) for k in BUDGETS);fullpass=sm['profile_pass']=='True' and sm['joint_pass']=='True';gpass=gm['profile_pass']=='True' and gm['joint_pass']=='True'
  conclusion=f"Expected pair top-three={topok}, primary correct={tuple(pair)==expected[j]}. Teacher mean complete coefficients {vec(dt['teacher_mean_alpha'])} document the nominated relation within the sampled domain. Full student passes both tolerances={fullpass}. Guided primary k={kg} passes both confirmation tolerances={gpass}; native-only primary k={kn} passes={nm['profile_pass']=='True' and nm['joint_pass']=='True'}. Guided corner MAE beats equal-budget native-only at {gwin}/5 budgets. This conditional profile comparison does not establish added value for pair discovery against a native pair-scanning baseline."
  lines += ['## Conclusion','',conclusion,'','Exact full-network identities validate accounting; they are not evidence of compactness or unique mechanism. These results do not establish causal neuron necessity, a ground-truth hidden decoder, global gate invariance, or final-population performance. Missing unrecorded historical inputs limit exposure claims. The teacher was accepted as a pilot despite failing its original all-primitive >=99% balanced-accuracy gate.','',f"FP32-vs-FP64 maximum errors={dt['FP32_vs_FP64_max']}. Numerical trace tolerance is atol=1e-9, rtol=1e-8; FP32 reference comparison atol=2e-6, rtol=2e-5. Scientific tolerances remained MAE<=.05, p95<=.10, joint MAE<=.10."]
  (run/f'case_output_{j}.md').write_text('\n'.join(lines)+'\n');summary.append([j,str(tuple(pair)),str(topok),f"{float(sm['corner_mae']):.5f}",f"{kg}: {float(gm['corner_mae']):.5f}, {gpass}",f"{kn}: {float(nm['corner_mae']):.5f}, {nm['profile_pass']=='True' and nm['joint_pass']=='True'}",f'{gwin}/5'])
 write(run/'secondary_label_diagnostics.json',secondary)
 protected=read(run/'protected_before.json');changed=[p for p,h in protected.items() if sha(p)!=h];assert not changed,changed
 s=['# Frozen-model workflow v0.4: completed','',table(['output','primary pair','expected top3','student MAE','guided primary k: MAE, both pass','native primary k: MAE, both pass','guided MAE wins'],summary),'','The executable workflow completed: 190 student-only pair nominations per output were locked before native ranking; fixed original-coefficient groups were locked before held-out development scoring. All three case reports show numerical thresholds, full corners, baseline/single/joint terms, true biases, cancellation, matched nuisance support, and explicit omitted remainders.','', 'A relationship nomination, complete-response fidelity, compactness, and added value are distinct results. The exact original gates explain a context-dependent hinge/cancellation computation. Full identities validate the accounting; reduced groups must independently meet the declared tolerances. Native-only comparisons test student profile guidance conditional on the nominated pair. There is no native-only pair-discovery baseline, so incremental value for discovering pairs remains unsupported.','', 'This is an auditable exploratory analysis with prospectively locked development checks, not human-blind discovery. Complete-corner hash partitioning and final/test/probe exclusions condition the population. Model-training overlap is explicitly tagged; held-out explanation inputs are not necessarily unseen during model training. Unrecorded historical exposure cannot be excluded.','',f'All {len(protected)} prior protected files retain their hashes. The reserved final file was accessed only by the isolated input-identity indexer; labels were never loaded and no final inputs were scored. Teacher/student/P/Q provenance was verified. No model training, fitted coefficients, hidden interventions, weight edits, or extra cases were performed.','', '[Output 4 report](case_output_4.md) · [Output 6 report](case_output_6.md) · [Output 0 report](case_output_0.md)','', '[Protocol](protocol.json) · [Manifests](context_manifest.json) · [Metrics](confirmation_metrics.csv) · [Discovery lock](discovery_lock.json) · [Native lock](native_lock.json) · [Execution log](execution.log)','', 'Execution: all analysis phases completed on CUDA. See exit_status for the orchestrator process result and tests.log for executed test results. Analysis stops here; no final scoring or next experiment is launched.']
 (run/'SUMMARY.md').write_text('\n'.join(s)+'\n');write(run/'complete.json',{'status':'complete','timestamp':now(),'protected_files_verified':len(protected),'reports':{f'case_output_{j}.md':sha(run/f'case_output_{j}.md') for j in OUTPUTS},'summary_sha256':sha(run/'SUMMARY.md'),'no_training':True,'no_interventions':True,'final_population_scored':False})
 print(run/'SUMMARY.md',flush=True)
